INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''CMT'' (Cut, Make, Trim) as a garment manufacturing business model?', '["A factory only performs cutting, sewing, and trimming operations on fabric supplied by the buyer, without sourcing raw materials itself","A factory that only performs fabric dyeing, unrelated to garment assembly","A quality inspection standard used in garment export","A type of sewing machine used for trimming loose threads"]'::jsonb, 'A factory only performs cutting, sewing, and trimming operations on fabric supplied by the buyer, without sourcing raw materials itself', 'In a CMT arrangement, the buyer supplies fabric and trims, and the factory is paid only for the cutting, sewing (making), and trimming labor — the factory doesn''t source or own the raw materials, distinguishing it from full-package (FOB) manufacturing.', 1, '{"cmt-model"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is ''FOB'' (Free On Board) pricing typically include, in garment sourcing, that CMT pricing does NOT?', '["The full cost of raw materials (fabric, trims) plus manufacturing, since the factory sources everything itself under FOB","FOB pricing only covers shipping costs, nothing else","FOB and CMT pricing always include exactly the same cost components","FOB pricing excludes labor costs entirely"]'::jsonb, 'The full cost of raw materials (fabric, trims) plus manufacturing, since the factory sources everything itself under FOB', 'Under FOB terms, the factory sources and pays for fabric and trims itself (not just labor as in CMT) and the FOB price covers the complete garment cost up to being loaded for shipment — a full-package manufacturing responsibility distinct from CMT''s labor-only scope.', 2, '{"fob-pricing"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''PP meeting'' (Pre-Production meeting) held for before bulk garment production begins?', '["A meeting between buyer, factory, and relevant teams to review and confirm all production details (fabric, trims, construction, timeline) before mass production starts","A meeting held only after all garments have already shipped","A meeting exclusively about factory worker payroll","A meeting that only discusses fabric dyeing recipes"]'::jsonb, 'A meeting between buyer, factory, and relevant teams to review and confirm all production details (fabric, trims, construction, timeline) before mass production starts', 'A PP meeting brings together relevant stakeholders (merchandiser, QA, production team, sometimes the buyer) to confirm every production detail — approved fabric/trims, construction specs, timeline — is aligned and correct BEFORE committing to full bulk production, catching potential issues early.', 1, '{"pp-meeting"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''PP sample'' in the apparel development/approval process?', '["A sample garment made using the actual bulk production fabric/trims/process, for final approval before mass production begins","The very first rough design sketch of a garment","A random sample pulled from an already-shipped order for record-keeping","A sample used only for photography/marketing purposes"]'::jsonb, 'A sample garment made using the actual bulk production fabric/trims/process, for final approval before mass production begins', 'A PP (pre-production) sample is made using the exact fabric, trims, and construction method intended for bulk production, serving as the final checkpoint for buyer approval before the factory commits to producing the full order quantity.', 1, '{"pp-sample"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why is it important that a PP sample uses the ACTUAL bulk fabric/trims rather than earlier prototype materials?', '["Only the actual bulk materials can reveal how the real production fabric behaves (shrinkage, drape, color) and confirm the final product will match approved specifications","Material choice for a PP sample has no bearing on whether bulk production will match specifications","PP samples are purely decorative and never actually influence the approval decision","Earlier prototype materials are always identical to final bulk materials with zero difference"]'::jsonb, 'Only the actual bulk materials can reveal how the real production fabric behaves (shrinkage, drape, color) and confirm the final product will match approved specifications', 'Since fabric properties (shrinkage, hand-feel, exact shade) can differ between an early prototype fabric and the actual bulk fabric lot, only a PP sample made with true bulk materials can reliably confirm the final production garment will meet approved specifications.', 2, '{"pp-sample-materials"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''size set'' sample production used to verify?', '["That the pattern grading across the full size range (S, M, L, XL, etc.) produces correctly proportioned, well-fitting garments at every size","The exact color shade of a single sample garment","The total number of garments an order requires","The factory''s compliance with labor law regulations"]'::jsonb, 'That the pattern grading across the full size range (S, M, L, XL, etc.) produces correctly proportioned, well-fitting garments at every size', 'A size set sample makes one garment in EVERY size of the order (not just the sample/base size), verifying that grading produced correctly scaled, well-proportioned garments across the entire size range before bulk cutting begins.', 1, '{"size-set-sample"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''trim card'' (or trim sheet) approval in apparel development?', '["Buyer approval of all the actual trims (buttons, zippers, labels, thread) to be used, often with physical samples attached to a reference card","A financial document tracking a factory''s profit margin","A card given to workers tracking their daily attendance","A record of fabric roll numbers used in production"]'::jsonb, 'Buyer approval of all the actual trims (buttons, zippers, labels, thread) to be used, often with physical samples attached to a reference card', 'A trim card physically displays/lists all trims (buttons, zippers, labels, drawcords, thread color, etc.) intended for the order, submitted for buyer approval to ensure the correct components are used in bulk production.', 1, '{"trim-card"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is a ''washing/laundry'' standard sometimes required for denim or garment-washed products before shipment approval?', '["An approved reference sample showing the exact intended wash effect (color, hand-feel, distressing) that bulk production must match","A hygiene certification unrelated to the garment''s visual appearance","A requirement that all garments must be laundered by the end customer before wearing","A standard measuring only the water temperature used in the factory''s laundry"]'::jsonb, 'An approved reference sample showing the exact intended wash effect (color, hand-feel, distressing) that bulk production must match', 'A wash standard is an approved physical reference sample (showing the target color fade, hand-feel, or distressing effect) that the bulk-washed garments must visually and physically match, ensuring consistent wash appearance across the full order.', 2, '{"wash-standard"}'::text[]);
